# R1: Read the list L of 45 distinct positive integers
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]

# R2: Determine if partition exists
from itertools import combinations

# generate all possible triples (a,b,c) where a + b = c
triples = [(a, b, c) for c in L for a, b in combinations(L, 2) if a + b == c]

def exact_cover(elements, subsets):
    if not elements:
        return []
    # map each element to subsets containing it
    elem_to_subs = {e: [] for e in elements}
    for i, sub in enumerate(subsets):
        for e in sub:
            if e in elem_to_subs:
                elem_to_subs[e].append(i)
    # choose element with fewest covering subsets
    chosen_elem = min(elements, key=lambda e: len(elem_to_subs[e]))
    for sub_idx in elem_to_subs[chosen_elem]:
        sub = subsets[sub_idx]
        new_elements = elements - set(sub)
        new_subsets = [s for j, s in enumerate(subsets) if j != sub_idx and not set(s) & set(sub)]
        result = exact_cover(new_elements, new_subsets)
        if result is not None:
            return [sub] + result
    return None

solution = exact_cover(set(L), triples)

# R3: Output one complete example of the 15 triples if exists
if solution:
    print("Solution found:")
    for a, b, c in solution:
        print(f"({a}, {b}, {c})")
    import json
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}
    print(f"WITNESS: {json.dumps(witness)}")
else:
    print("No partition exists.")
    import json
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "proof", "argument": "No exact cover of triples exists for the given set."}
    print(f"WITNESS: {json.dumps(witness)}")
